255	  private HoodieInstant readCommit(String instantTime, GenericRecord record, boolean loadDetails) {
256	    final String action = record.get(ACTION_TYPE_KEY).toString();
257	    final String stateTransitionTime = (String) record.get(STATE_TRANSITION_TIME);
258	    if (loadDetails) {
259	      getMetadataKey(action).map(key -> {
260	        Object actionData = record.get(key);
261	        if (actionData != null) {
262	          if (action.equals(HoodieTimeline.COMPACTION_ACTION)) {
263	            this.readCommits.put(instantTime, HoodieAvroUtils.indexedRecordToBytes((IndexedRecord) actionData));
264	          } else {
265	            this.readCommits.put(instantTime, actionData.toString().getBytes(StandardCharsets.UTF_8));
266	          }
267	        }
268	        return null;
269	      });
270	    }
271	    return instantGenerator.createNewInstant(HoodieInstant.State.valueOf(record.get(ACTION_STATE).toString()), action,
272	        instantTime, stateTransitionTime);
273	  }
