  /**
   * Builds a record filter that keeps only the records that fall in the given time range (when
   * {@code rangeFilter} is non-null) and match the requested instant state (when {@code state} is
   * present). An empty {@code state} matches all states.
   */
  private static Function<GenericRecord, Boolean> getInstantsFilter(
      @Nullable HoodieArchivedTimeline.ClosedClosedTimeRangeFilter rangeFilter,
      Option<HoodieInstant.State> state) {
    return record -> {
      if (rangeFilter != null
          && !rangeFilter.isInRange(record.get(HoodieTableMetaClient.COMMIT_TIME_KEY).toString())) {
        return false;
      }
      if (state.isPresent()) {
        Object actionState = record.get(ACTION_STATE);
        return actionState != null && state.get().toString().equals(actionState.toString());
      }
